(* input: days present in US per year for substantial presence test *)
type presence_days = {
  current_year : int;
  first_preceding_year : int;
  second_preceding_year : int;
}

(* weighted sum of days per multiplier table: current=1, 1st preceding=1/3, 2nd preceding=1/6 *)
let weighted_day_sum (days : presence_days) : float =
  (float_of_int days.current_year *. 1.0) +.
  (float_of_int days.first_preceding_year *. (1.0 /. 3.0)) +.
  (float_of_int days.second_preceding_year *. (1.0 /. 6.0))

(* substantial presence test of 7701(b)(3)(A): 31-day floor in current year AND weighted 3-year sum >= 183 *)
let meets_substantial_presence_test (days : presence_days) : bool =
  days.current_year >= 31 &&
  weighted_day_sum days >= 183.0

type individual = {
  days_present_current_year : int;
  country_of_closer_connection : string option; (* foreign country individual has closer connection to *)
}

(* tax home per section 911(d)(3), without regard to second sentence thereof *)
let has_tax_home_in_foreign_country (individual : individual) (foreign_country : string) : bool =
  (* unresolved cross-reference — needs §911(d)(3) (without regard to second sentence) *)
  failwith "unresolved cross-reference"

(* clause (i): fewer than 183 days present in United States during current year *)
let is_present_fewer_than_183_days (individual : individual) : bool =
  individual.days_present_current_year < 183

(* clause (ii): closer connection to foreign country than to United States *)
let has_closer_connection_to_foreign_country (individual : individual) (foreign_country : string) : bool =
  match individual.country_of_closer_connection with
  | Some country -> country = foreign_country
  | None -> false

(* exception to substantial presence test: both clauses (i) and (ii) must hold *)
let qualifies_for_closer_connection_exception (individual : individual) (foreign_country : string) : bool =
  is_present_fewer_than_183_days individual &&
  has_tax_home_in_foreign_country individual foreign_country &&
  has_closer_connection_to_foreign_country individual foreign_country

type testing_period = {
  actual_days_present : int; (* physical presence days in the testing period *)
  absence_days_to_credit : int; (* days absent that individual asks to treat as present *)
  testing_period_length : int; (* total days from start of 31-day period through end of election year *)
}

(* (b)(4)(A)(iv)(I): present at least 31 consecutive days in the election year *)
let is_present_31_consecutive_days (days_present_in_31_day_period : int) : bool =
  days_present_in_31_day_period >= 31

(* absence days credited as presence, capped at 5 in the aggregate *)
let effective_days_present (period : testing_period) : int =
  let credited_absence = min period.absence_days_to_credit 5 in
  period.actual_days_present + credited_absence

(* (b)(4)(A)(iv)(II): present >= 75% of the testing period, with up to 5 absent days credited as present *)
let is_present_75_percent_of_testing_period (period : testing_period) : bool =
  float_of_int (effective_days_present period) >=. 0.75 *. float_of_int period.testing_period_length

(* (b)(4)(A)(iv): both the 31-consecutive-day test and the 75%-of-testing-period test must hold *)
let is_present_for_election_year_test (days_present_in_31_day_period : int) (period : testing_period) : bool =
  is_present_31_consecutive_days days_present_in_31_day_period &&
  is_present_75_percent_of_testing_period period

type sports_event = {
  organized_for_charity_benefit : bool; (* (I): event's primary purpose benefits a 501(c)(3) org exempt under 501(a) *)
  all_net_proceeds_contributed : bool; (* (II): all net proceeds go to that organization *)
  work_done_by_volunteers : bool; (* (III): volunteers perform substantially all work of the event *)
}

(* qualifying charitable sports event under 7701(b)(5)(A)(iv)(I)-(III) *)
let is_qualifying_charitable_event (event : sports_event) : bool =
  event.organized_for_charity_benefit &&
  event.all_net_proceeds_contributed &&
  event.work_done_by_volunteers

type athlete = {
  is_professional : bool;
  temporarily_in_us_to_compete : bool;
  event : sports_event;
}

(* 7701(b)(5)(A)(iv): professional athlete temporarily present to compete in a qualifying charitable sports event *)
let is_exempt_professional_athlete (athlete : athlete) : bool =
  athlete.is_professional &&
  athlete.temporarily_in_us_to_compete &&
  is_qualifying_charitable_event athlete.event

type visa_classification =
  | J_Exchange_Visitor  (* INA section 101(15)(J) *)
  | Q_International_Cultural_Exchange  (* INA section 101(15)(Q) *)
  | Student
  | Other

type individual = {
  visa_classification : visa_classification;
  substantially_complies_with_presence_requirements : bool;
}

(* is_teacher_or_trainee : 7701(b)(5)(C) - individual temporarily present under INA (J) or (Q) status, other than as a student, who substantially complies with requirements for that presence *)
let is_teacher_or_trainee (individual : individual) : bool =
  (match individual.visa_classification with
   | J_Exchange_Visitor | Q_International_Cultural_Exchange -> true
   | Student | Other -> false)
  && individual.substantially_complies_with_presence_requirements

