type alien_individual = {
  initial_residency_start : int;
  initial_residency_end : int;
  consecutive_resident_years : int;
  ceased_residency : bool;
  subsequent_residency_start : int option;
}

let has_initial_residency_period (individual : alien_individual) : bool =
  individual.consecutive_resident_years >= 3

let resumes_residency_within_window (individual : alien_individual) : bool =
  individual.ceased_residency &&
  match individual.subsequent_residency_start with
  | None -> false
  | Some resumed_year -> resumed_year <= individual.initial_residency_end + 3

