let tax_under_section_871 (individual : alien_individual) : float =
  (* unresolved — needs §871 *)
  failwith "unresolved cross-reference"

let applies_877_coordination (individual : alien_individual) : bool =
  has_initial_residency_period individual &&
  resumes_residency_within_window individual &&
  tax_under_section_877b individual >. tax_under_section_871 individual

type status_application = {
  had_pending_adjustment_of_status : bool; (* clause (i): application for adjustment of status pending *)
  took_other_lpr_steps : bool; (* clause (ii): other steps to apply for lawful permanent resident status *)
}

(* subparagraph (B) closer-connection exception is barred if either clause (i) or (ii) occurred during the current year *)
let subparagraph_b_barred (status : status_application) : bool =
  status.had_pending_adjustment_of_status ||
  status.took_other_lpr_steps

(* individual temporarily present in US, for foreign government-related status *)
type individual = {
  has_diplomatic_status : bool;
  has_qualifying_diplomatic_or_consular_visa : bool; (* Secretary, after consult w/ Sec of State, determines full-time diplomatic/consular status *)
  is_full_time_employee_of_international_org : bool;
  immediate_family_member_of : individual option; (* family link to an individual under clause (i) or (ii) *)
}

(* clause (i): diplomatic status or qualifying visa *)
let has_diplomatic_or_consular_status (individual : individual) : bool =
  individual.has_diplomatic_status ||
  individual.has_qualifying_diplomatic_or_consular_visa

(* clause (ii): full-time employee of international organization *)
let is_international_org_employee (individual : individual) : bool =
  individual.is_full_time_employee_of_international_org

(* clause (i) or (ii), for use by clause (iii) *)
let is_described_in_clause_i_or_ii (individual : individual) : bool =
  has_diplomatic_or_consular_status individual ||
  is_international_org_employee individual

(* clause (iii): immediate family member of individual described in (i) or (ii) *)
let is_immediate_family_of_qualifying_individual (individual : individual) : bool =
  match individual.immediate_family_member_of with
  | Some related -> is_described_in_clause_i_or_ii related
  | None -> false

let is_foreign_government_related_individual (individual : individual) : bool =
  has_diplomatic_or_consular_status individual ||
  is_international_org_employee individual ||
  is_immediate_family_of_qualifying_individual individual

(* individual : capture whether individual has established closer connection
   to a foreign country than to the United States, per (b)(2)(C)(i) *)
type individual = {
  has_closer_connection_to_foreign_country : bool;
}

(* is_day_disregarded : a day of US presence is disregarded under clause (i)
   only if the individual has the closer foreign connection AND the 10-day
   cap in clause (ii) has not already been used up *)
let is_day_disregarded (individual : individual) (days_already_disregarded : int) : bool =
  individual.has_closer_connection_to_foreign_country
  && days_already_disregarded < 10

(* date range for a calendar year or taxable year *)
type date = { year : int; month : int; day : int }

type period = { start_date : date; end_date : date }

type taxable_year =
  | Calendar_year of period
  | Fiscal_year of period (* taxable year other than a calendar year, per subparagraph (A) *)

type individual = {
  resident_under_paragraph_1 : int -> bool; (* treated as resident of US under (b)(1) for given calendar year *)
  taxable_year_after_subparagraph_a : taxable_year; (* individual's taxable year after application of subparagraph (A) *)
}

(* intersection of a taxable-year period with the given calendar year *)
let portion_within_calendar_year (period : period) (calendar_year : int) : period option =
  (* unresolved — needs computation of overlap between period and calendar year, not specified in provision text *)
  failwith "unresolved cross-reference"

(* (b)(9)(B): resident status for the portion of a fiscal taxable year falling within a calendar year in which the individual is a resident under paragraph (1) *)
let resident_portion_for_fiscal_year_taxpayer (individual : individual) (calendar_year : int) : period option =
  match individual.taxable_year_after_subparagraph_a with
  | Calendar_year _ -> None (* condition (ii) fails: taxable year is a calendar year *)
  | Fiscal_year period ->
      if individual.resident_under_paragraph_1 calendar_year (* condition (i) *)
      then portion_within_calendar_year period calendar_year
      else None

type individual = {
  is_lawful_permanent_resident : int -> bool; (* true if lawful permanent resident during given calendar year, clause (i) *)
  meets_substantial_presence_test : int -> bool; (* substantial presence test of paragraph (3), clause (ii) *)
  makes_first_year_election : int -> bool; (* first year election of paragraph (4), clause (iii) *)
}

(* is_resident_alien : alien individual treated as US resident for given calendar year iff clause (i), (ii), or (iii) holds, subparagraph (A) *)
let is_resident_alien (individual : individual) (year : int) : bool =
  individual.is_lawful_permanent_resident year ||
  individual.meets_substantial_presence_test year ||
  individual.makes_first_year_election year

(* is_nonresident_alien : individual is nonresident alien iff neither US citizen nor resident alien within meaning of (A), subparagraph (B) *)
let is_nonresident_alien (individual : individual) (is_citizen : bool) (year : int) : bool =
  not is_citizen && not (is_resident_alien individual year)
